/* Intermediate6: standard on-demand Event Functions; bounded runtime model. */
(function () {
  const N=AG.aws.n,REGION='ap-south-1',JOBS='arn:aws:sqs:ap-south-1:123456789012:photo-jobs',FAILURES='arn:aws:sqs:ap-south-1:123456789012:photo-failures';
  const SVG='<svg xmlns="http://www.w3.org/2000/svg" width="320" height="240" viewBox="0 0 320 240"><rect width="320" height="240" fill="red"/></svg>';
  const EVENT=()=>({Records:[{eventSource:'aws:s3',s3:{bucket:{name:'shop-uploads'},object:{key:'uploads/kurta.svg',versionId:'v-photo'}}}]});
  const DEST=()=>({OnFailure:{Destination:FAILURES}}),file=x=>({content:JSON.stringify(x,null,2)}),clone=x=>JSON.parse(JSON.stringify(x));
  const table=s=>'<div class="tbl-wrap">'+s+'</div><p class="muted">Phone par table ke baaki columns sideways swipe karo.</p>';
  function seed(){return {region:REGION,lambdaConcurrencyQuota:1000,
    lambdas:[{name:'photo-resize',runtime:'python3.12',handler:'app.handler',roleName:'shop-lambda',state:'Active',lastUpdateStatus:'Successful',memory:128,timeout:3,architectures:['x86_64'],reservedConcurrency:2,busyConcurrent:2,revisionId:'r0',workload:{kind:'svg-fixture',sourceBucket:'shop-uploads',outputBucket:'shop-thumbs',sourceKey:'uploads/kurta.svg',baseMs:800,ioFloorMs:300,initMs:300}},{name:'courier-webhook',runtime:'python3.12',handler:'webhook.handler',state:'Active',memory:256,timeout:10,invokeResult:'{"accepted":true}'}],
    roles:[{name:'shop-lambda',lambda:{trust:'lambda.amazonaws.com',sourceBucket:'shop-uploads',outputBucket:'shop-thumbs',receiveQueues:[JOBS],sendQueues:[FAILURES]}}],
    buckets:[{name:'shop-uploads',region:REGION,public:false,encryption:true,versioning:true,versions:{'uploads/kurta.svg':[{versionId:'v-photo',body:SVG,size:SVG.length,storageClass:'STANDARD',deleteMarker:false}]}},{name:'shop-thumbs',region:REGION,public:false,encryption:true,objects:[]}],
    queues:[{name:'photo-jobs',arn:JOBS,url:'https://sqs.ap-south-1.amazonaws.com/123456789012/photo-jobs',visibilityTimeout:120,isFifo:false,messages:[]},{name:'photo-failures',arn:FAILURES,url:'https://sqs.ap-south-1.amazonaws.com/123456789012/photo-failures',visibilityTimeout:120,isFifo:false,messages:[]}],eventSourceMappings:[],
    logGroups:[{name:'/aws/lambda/photo-resize',events:['fixture-request-old Task timed out after 3.00 seconds','TooManyRequestsException: ReservedFunctionConcurrentInvocationLimitExceeded; configured reserve 2']}]
  };}
  const fn=s=>(s.account.lambdas||[]).find(f=>f.name==='photo-resize');
  function capacity(s){const f=fn(s);return !!f&&!f.pendingConfig&&f.memory>=512&&f.memory<=2048&&f.timeout>=15&&f.timeout<=30&&f.state==='Active'&&AG.lambdaTiming(f).warmMs+AG.lambdaTiming(f).initMs<=2000&&f.reservedConcurrency>=10&&f.reservedConcurrency<=20&&Math.ceil(10*AG.lambdaTiming(f).warmMs/1000)<=f.reservedConcurrency;}
  function asyncReady(s){const f=fn(s),c=f&&f.asyncConfigs&&f.asyncConfigs.$LATEST;return !!c&&c.MaximumRetryAttempts===2&&c.MaximumEventAgeInSeconds===3600&&c.DestinationConfig&&c.DestinationConfig.OnFailure&&c.DestinationConfig.OnFailure.Destination===FAILURES;}
  function mappingReady(s){const rows=(s.account.eventSourceMappings||[]).filter(m=>m.functionName==='photo-resize');return rows.length===1&&rows[0].eventSourceArn===JOBS&&rows[0].batchSize===10&&rows[0].state==='Enabled'&&!rows[0].pendingState&&rows[0].responseTypes.length===1&&rows[0].responseTypes[0]==='ReportBatchItemFailures';}
  function derivatives(s){const b=(s.account.buckets||[]).find(b=>b.name==='shop-thumbs'),rows=b&&b.objects;return Array.isArray(rows)&&rows.length===3&&[64,128,256].every(size=>rows.some(o=>o.sourceVersion==='v-photo'&&o.width===size&&o.height===size&&o.body===SVG.replace('width="320"','width="'+size+'"').replace('height="240"','height="'+size+'"')));}
  function preserved(s){const a=seed(),f=fn(s),src=(s.account.buckets||[]).find(b=>b.name==='shop-uploads'),versions=src&&src.versions&&src.versions['uploads/kurta.svg'];return !!f&&f.runtime==='python3.12'&&f.handler==='app.handler'&&f.roleName==='shop-lambda'&&(s.account.lambdas||[]).length===2&&JSON.stringify(s.account.lambdas.find(f=>f.name==='courier-webhook'))===JSON.stringify(a.lambdas[1])&&(s.account.buckets||[]).length===2&&s.account.buckets.every(b=>!b.public&&b.encryption)&&Array.isArray(versions)&&versions[0].versionId==='v-photo'&&versions[0].body===SVG&&!versions[0].deleteMarker&&src.versioning&&JSON.stringify(s.account.roles)===JSON.stringify(a.roles)&&JSON.stringify(s.account.queues)===JSON.stringify(a.queues);}
  function invokeProof(s,out){const f=fn(s),r=s.downloads&&s.downloads[out];return !!f&&!!r&&!r.error&&r.functionName===f.name&&r.revisionId===(f.revisionId||'r0')&&r.executedVersion==='$LATEST';}
  const SOLUTION=[
    'aws lambda update-function-configuration --function-name photo-resize --memory-size 1024 --timeout 15',
    'aws lambda wait function-updated-v2 --function-name photo-resize',
    'aws lambda put-function-concurrency --function-name photo-resize --reserved-concurrent-executions 10',
    'aws lambda put-function-event-invoke-config --function-name photo-resize --maximum-retry-attempts 2 --maximum-event-age-in-seconds 3600 --destination-config file://destination.json',
    'aws lambda create-event-source-mapping --function-name photo-resize --event-source-arn '+JOBS+' --batch-size 10 --function-response-types ReportBatchItemFailures --enabled',
    'aws lambda list-event-source-mappings --function-name photo-resize',
    'aws lambda invoke --function-name photo-resize --cli-binary-format raw-in-base64-out --payload file://event.json invoke.json'
  ];
  const TASKS=[{text:'Modeled fixture p99 ≤2 s; memory 512..2048 MB, timeout 15..30 s, reserve 10..20 and 10 RPS capacity',check:capacity},{text:'Async retry 2 / age 3600 s / existing failure queue on original function',check:asyncReady},{text:'Single Enabled jobs mapping, batch 10 and ReportBatchItemFailures',check:mappingReady},{text:'Three correct derivatives of exact v-photo; original source preserved',check:derivatives},{text:'invoke.json contains successful current-$LATEST result for original source version',check:s=>{const r=s.downloads&&s.downloads['invoke.json'],x=r&&r.body&&r.body.results;return invokeProof(s,'invoke.json')&&Array.isArray(x)&&x.length===1&&x[0].sourceVersion==='v-photo'&&x[0].written+x[0].duplicates===3;}},{text:'Original functions, versioned input, private buckets, role and empty queues preserved',check:preserved}];
  function budget(k){const memory=[128,256,512,1024,2048,3072][k.memory],calls=[2e5,1e6,5e6,1e7][k.calls],slots=[0,2,10][k.pc],cold=[0,1,5,10][k.cold]/100;
    const m=AG.lambdaTiming({memory,workload:{baseMs:k.base,ioFloorMs:100,initMs:300}}),needed=Math.max(1,Math.ceil(10*m.warmMs/1000)),coverage=Math.min(1,slots/needed),remainingCold=cold*(1-coverage),p99=m.warmMs+(remainingCold>=0.01?m.initMs:0),gb=memory/1024;
    const arm=k.arch===1,onRate=arm?0.0000133334:0.0000166667,pcRate=arm?0.0000077778:0.0000097222,allocRate=arm?0.0000033334:0.0000041667;
    const on=calls*(1-coverage)*(m.warmMs+cold*m.initMs)/1000*gb*onRate,pcRun=calls*coverage*m.warmMs/1000*gb*pcRate,allocation=slots*gb*30*24*3600*allocRate,requests=calls/1e6*.20,total=on+pcRun+allocation+requests;
    return {memory,calls,slots,m,needed,p99,total,allocation,compute:on+pcRun,requests,ok:calls>=5e6&&k.base>=700&&cold>=0.01&&p99<=2000&&total*88<=7000};}
  function Q(q,correct,wrong,answer,explain){const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};}
  AG.registerLevels('intermediate',[{
    id:'lambda',icon:'⚡',title:'Lambda + API Gateway — retries, limits aur output evidence',badge:'Serverless Sardar',
    objectives:['<b>Invocation:</b> sync, async aur poll-based event source mapping distinguish karo','<b>Performance:</b> timeout, memory/CPU, cold init aur concurrency controls','<b>HTTP:</b> API type/auth/timeout choose karo; API keys authentication nahi','<b>Correctness:</b> exact source version, duplicate-safe outputs, partial batch response','<b>Cost:</b> billed duration, architecture aur paid provisioned capacity compare karo','<b>Evidence:</b> function error/body inspect karo; HTTP200 alone success nahi'],
    hook:{when:'SHOPKARO · SELLER PHOTOS + COURIER WEBHOOK · FICTIONAL COURSE STORY',title:'“200 photos/day ke liye 24-hour EC2, ya events par code?”',text:'Sellers product photos upload karte hain; ShopKaro ko three thumbnail sizes chahiye. Courier partner status webhook bhi bhejta hai. Ravi full-time EC2 suggest karta hai. Neha ko event-driven processing chahiye, par duplicate events, large-photo timeout aur failed deliveries ka clear plan bhi chahiye. Automatic scaling is not unlimited capacity or automatic business correctness.'},
    steps:[
      {q:'Function, trigger aur execution environment ka simple model?',analogy:'Full-time electrician har ghante paid duty par hai; on-call electrician event aane par kaam karta hai. Tools ready karne ka startup time aur simultaneous calls ki capacity phir bhi matter karti hai.',body:'<p>Standard on-demand Lambda Event Function is code plus configured runtime, execution role and trigger. AWS manages infrastructure; application code, dependencies, permissions, retries and data correctness remain your responsibility. Execution environment may be reused; reuse or a fixed idle interval is not guaranteed.</p>',points:['S3 photo event can run a short worker; courier API can synchronously return an acknowledgement. Long workflow orchestration and durable state need explicit design. Do not keep business state only in process memory or /tmp.','Warm request reuses initialization; cold initialization loads runtime/dependencies/code. Freeze/thaw reuse and creating a new environment are different events. No documented “15 minutes idle then always cold” rule.','Course scope is standard on-demand Event Functions. Current Lambda also has Managed Instances, durable/Web Function models with different limits; do not apply one model’s quotas/pricing blindly to every Lambda offering.'],asli:'Action: dry run follows one uploaded source version through init, execution, retry and failure capture. Local lab executes handler on host Python; in-app runtime uses an explicit bounded SVG fixture.'},
      {q:'Sync, async aur event source mapping mein retry owner kaun?',analogy:'Phone call caller wait karta hai; postal drop backend queue mein wait karta hai; courier collection worker queue se batch uthata hai. Failure response ka owner har route mein alag hai.',body:table('<table><tr><th>Path</th><th>Example</th><th>Failure owner</th></tr><tr><td>Sync</td><td>API Gateway, direct RequestResponse</td><td>Caller sees response; caller retry policy</td></tr><tr><td>Async push</td><td>S3, SNS, EventBridge</td><td>Lambda-owned internal queue, retry/age/destination</td></tr><tr><td>Poll-based mapping</td><td>SQS, Kinesis, DynamoDB Streams</td><td>Source/mapping-specific batch/retry rules</td></tr></table>'),points:['Function errors in async push get two additional attempts by default. Throttling/system errors use backoff and event-age handling (up to 6 hours by default); “exactly two retries for every error” is wrong. Duplicate deliveries are possible even without an error.','For SQS, visibility/redrive and handler batch response govern retries. Enable ReportBatchItemFailures and return failed message IDs. Async function destinations do not replace SQS redrive policy.','SQS visibility must be at least function timeout; AWS recommends at least 6× timeout plus batching window. FIFO needs ordering-aware partial failure handling; this lab uses Standard SQS.'],asli:'Action: terminal configures both async failure capture and an SQS mapping because ShopKaro supports two ingestion paths. Manual invoke verifies handler result; automatic queue consumption is not modeled.'},
      {q:'Timeout, payload, memory aur /tmp ke limits kya mean karte hain?',code:'aws lambda get-function-configuration --function-name photo-resize\naws lambda update-function-configuration --function-name photo-resize --memory-size 1024 --timeout 15\naws lambda wait function-updated-v2 --function-name photo-resize',analogy:'Task deadline, parcel size, worker resources aur temporary desk space alag controls hain. Bada desk business durability nahi deta; extra CPU I/O wait ko automatically solve nahi karta.',body:table('<table><tr><th>Standard on-demand scope</th><th>Current documented value</th></tr><tr><td>Execution timeout</td><td>1..900 seconds</td></tr><tr><td>Memory / temporary storage</td><td>128..10,240MB /512..10,240MB</td></tr><tr><td>Buffered sync request/response</td><td>6MB each</td></tr><tr><td>Async payload</td><td>1MB since October 2025</td></tr><tr><td>Streamed sync response</td><td>Up to200MB; separate bandwidth rules</td></tr></table>'),points:['CPU entitlement increases with memory; workload benchmark decides speed/cost. “4× memory always4× faster” is not a valid guarantee. IO waits, dependencies and downstream limits can dominate.','Deployment ZIP size, layers, container image size and invocation payload are separate quotas. Current standard ZIP uncompressed package limit 250 MB including layers; image limit 10 GB. Use supported runtimes/architecture-compatible dependencies.','/tmp is ephemeral and may survive environment reuse; no durable-state promise. More than 512 MB temporary storage has separate charges. Current Managed Instances support up to 90-minute eligible async/ESM invocations; standard on-demand function timeout remains 15 minutes.'],asli:'Action: inspect memory/timeout and actual error body before tuning. A larger timeout hides slow code unless latency target and downstream concurrency also fit.'},
      {q:'Reserved aur provisioned concurrency ka difference?',code:'aws lambda get-function-concurrency --function-name photo-resize\naws lambda put-function-concurrency --function-name photo-resize --reserved-concurrent-executions 10',analogy:'Reserved capacity means restaurant ke ten seats sirf tumhare group ke liye reserved hain. Provisioned readiness means seats par staff/table setup pehle se ready hai. Reserved seat count warm food guarantee nahi hai.',body:'<p>Concurrency is in-flight work, approximately arrival rate × execution duration. Common Regional default is 1,000 shared concurrent executions, but new accounts may have lower quotas. Function scaling rates and downstream systems also limit throughput.</p>',points:['Reserved concurrency is an exclusive capacity reservation and a maximum cap; no separate reservation charge. Reserved0 throttles the function. Keep required account unreserved pool; reserve does not pre-initialize environments.','Provisioned concurrency allocates initialized environments on a published version or alias, with additional allocation and execution pricing. $LATEST does not support PC. Requests beyond prepared capacity can spill into on-demand cold starts.','10 RPS ×0.8 s means roughly 8 concurrent executions before safety/variance. Set a cap to protect DB/partner limits, then monitor ConcurrentExecutions, Throttles, Duration and downstream health. Concurrency and requests/second are not identical units.'],asli:'Action: course fixture starts with reserve 2 and two busy requests. Set reserve 10, then prove required10RPS capacity and latency fit after right-sizing; choosing an enormous cap does not satisfy downstream budget.'},
      {q:'Cold-start levers kya hain; VPC ko blindly avoid kyun nahi?',analogy:'Electrician ki toolkit light karna, stronger worker dena, prepared station rakhna ya prepared snapshot se start karna alag levers hain. Private warehouse ki zaroorat ho toh access route repair karo; warehouse requirement delete mat karo.',body:'<p>Measure initialization separately from handler execution. Reduce unnecessary startup/package work, benchmark memory/CPU and architecture, reuse safe clients, and compare supported SnapStart/provisioned concurrency against actual latency and cost needs.</p>',points:['Current SnapStart supports Java 11+, Python 3.12+, .NET 8+ and corresponding supported image formats. Published-version snapshot restore has uniqueness/connection-refresh requirements; support/Region/runtime must be checked. SnapStart is not universally free.','SnapStart does not support provisioned concurrency, EFS/S3Files or /tmp above 512 MB in current docs. PC reduces cold init within prepared capacity; lifecycle resets, spillover, downstream latency and handler failures still exist.','VPC access has no universal +100ms penalty. A function reaching private DB resources needs correct VPC configuration. Public subnet attachment does not assign the function a public IP; internet egress requires appropriate NAT/IPv6 path, or service endpoints for supported AWS APIs.'],asli:'Action: planner latency numbers are a declared CPU/IO teaching model, not AWS benchmarks. Real production choice needs measured cold/warm distributions and a concurrency/load test.'},
      {q:'HTTP API, REST API, WebSocket ya function URL?',analogy:'Courier ko simple doorbell chahiye ya full reception desk with protocol/auth/policies? Endpoint type business contract se choose karo; ek API key employee identity badge nahi hai.',body:table('<table><tr><th>Choice</th><th>Kab use</th><th>Review</th></tr><tr><td>HTTP API</td><td>Simple HTTP routing, JWT/IAM/Lambda authorizer</td><td>Feature set; integration timeout 30 s</td></tr><tr><td>REST API</td><td>Usage plans/keys, selected advanced API controls</td><td>API keys not authentication; extra cost/features</td></tr><tr><td>WebSocket API</td><td>Bidirectional connection messaging</td><td>Connection management/auth/message limits</td></tr><tr><td>Function URL</td><td>Simple direct HTTPS function endpoint</td><td>IAM/NONE plus resource permissions; fewer gateway controls</td></tr></table>'),points:['API Gateway account-level default is 10,000 RPS in many Regions; listed Regions default 2,500 RPS. Throttle/burst limits are not a blanket DDoS solution or exact hard per-customer billing limit. API type/features, WAF/Shield architecture and authentication are separate decisions.','REST regional/private integration timeout default 29 s can be raised with quota/trade-off approval; edge-optimized remains 29 s. HTTP API maximum 30 s. Long job API should often acknowledge/enqueue and expose status rather than hold the request open.','For new function URLs since October 2025, both lambda:InvokeFunctionUrl and lambda:InvokeFunction permissions matter. AWS_IAM uses signed authorized access; NONE needs deliberate resource policy review. Courier callbacks also need replay/idempotency and request authenticity checks.'],asli:'Action: choose endpoint and auth from the requirement. Terminal repairs the event worker; no fictional API Gateway deployment or HTTP-network proof is claimed.'},
      {q:'Memory badhane se bill kab ghatega, kab badhega?',analogy:'Faster worker ka hourly rate zyada ho sakta hai, par kaam kam waqt mein khatam ho toh total cost stable ya lower ho sakti hai. Idle prepared staff ka bill alag hai.',body:'<p>Gross standard on-demand example:5 million calls ×0.5GB ×0.2s =500,000GB-seconds. Approx US East x86 first-tier rate$0.0000166667/GB-s gives$8.33 duration plus$1 small-payload requests. Actual INIT/extensions, API Gateway, logs, S3, network and other charges add cost.</p>',points:['Current first-tier arm64 duration approx$0.0000133334/GB-s vs x86$0.0000166667; benchmark architecture compatibility/speed, do not assume fixed performance improvement. Prices are illustrative US East2025–26, not every Region. ₹88/$1 for arithmetic.','INIT duration is billed; idle on-demand execution does not accrue function execution duration, but provisioned concurrency, storage/log/network resources and other service activity can still cost money. No blanket “whole serverless stack idle=$0” promise.','PC needs allocation charges for prepared GB-seconds plus PC execution and request charges; spillover on-demand uses on-demand rate. Planner excludes free-tier/credits, discounts, PC recycle INIT and downstream costs; gross estimate is not an invoice.','Break-even against hypothetical$20/month always-on compute is only workload arithmetic. EC2/Fargate also need operations, capacity, availability, load balancing and network budget; compare equal requirements.'],asli:'Action: keep at least 5 million invocations and the declared workload complexity in planner. Lower memory bill without meeting p99 is not a valid optimization.'},
      {q:'Retries ke saath data correctness ka actual proof kya hai?',analogy:'Courier same parcel receipt do baar de sakta hai. Receipt key se duplicate identify karo, original parcel version read karo, aur already-present parcel ki contents verify karo. Sirf “request received” stamp final delivery nahi hai.',body:'<p>Use a stable event/business identity and an idempotent operation at the data store boundary. Local SVG lab keys outputs by source bucket/key/version and writes with a conditional create. Duplicate delivery compares existing bytes; a mismatching derivative fails visibly.</p>',points:['Source key can be overwritten before delayed event processing. Exact source VersionId avoids accidentally reading a newer image for an older event. S3 event keys are URL-encoded; decode space/plus correctly.','Separate output bucket or reviewed input-prefix filter prevents recursive triggers. Recursive loop detection supports selected service/SDK paths; it is not a substitute for avoiding the loop and monitoring cost/backlog.','Galti jo sab karte hain: retry non-idempotent side effects, treat HTTP200 as handler success, enable partial-batch flag without returning IDs, or let output trigger input again.','Production me kya hota hai: duplicate/out-of-order events, timeouts after partial writes, corrupt prior output, poison messages and quota exhaustion. Keep useful failure records, DLQ/replay tooling, observability and an owner for reprocessing. Interview follow-ups: who retries? Which exact source version? What happens after a partially written derivative set?'],asli:'Action: in-app invoke.json body plus source/output state must agree. Host handler test checks real local S3 bytes and concurrent duplicates; neither test proves a deployed AWS or Docker runtime.'},
    ],
    myth:[
      {myth:'“Fifteen minutes idle hue toh cold start guaranteed.”',sach:'No fixed idle timer contract. Environment reuse, init and cold-start distributions depend on runtime/workload/lifecycle.'},
      {myth:'“Reserved concurrency warm environments khareedti hai.”',sach:'Reserved sets exclusive capacity and cap. Provisioned concurrency prepares qualified environments and has extra pricing.'},
      {myth:'“StatusCode200 matlab worker ne correct output bana diya.”',sach:'Invoke may return200 plus FunctionError. Inspect response body and actual output/version evidence; DryRun/async202 are not completed work.'},
      {myth:'“Serverless means infinite scale aur whole stack ka idle bill zero.”',sach:'Quotas, scaling rate, downstream limits and paid resources remain. Function duration, prepared capacity, API/log/storage/network charges separate hain.'},
    ],
    playbook:{title:'Function ya always-on compute — decision guide',use:['Short event-driven standard Lambda tasks with explicit retry/idempotency contract','HTTP API for required simple HTTP controls; REST/WebSocket/URL when actual feature need matches','Memory/architecture tuning from measurements; reserved cap for downstream protection'],avoid:['Business state only in process memory or /tmp','Long jobs behind a synchronous HTTP deadline without reviewed async design','Unbounded retries, same input/output trigger path or assuming API keys authenticate callers'],how:['Name sync/async/poller path and retry owner','Set payload, deadline, concurrency and downstream budgets; benchmark cold/warm distribution','Use stable input version/business ID, conditional writes and scoped failure records','Inspect function error/body plus actual data and deployed delivery evidence'],redflags:['Fixed cold-start delay or VPC penalty quoted as guarantee','Two retries claimed for every invocation type/error','ReportBatchItemFailures flag with no failed-ID response','Provisioned concurrency on $LATEST or ignored spillover cost'],rule:'Work contract → invocation/retry owner → resource/latency limits → idempotency/failure capture → complete cost and real output evidence.'},
    exam:[
      {cue:'"short event-driven workload; least server management"',pick:'Standard Lambda candidate',why:'Check quotas, dependencies and downstream requirements; automatic scaling is bounded.'},
      {cue:'"standard job exceeds15 minutes"',pick:'Review Fargate/Batch/EC2 or different supported compute model',why:'Standard timeout 900 s; current eligible Managed Instances exceptions have different scope.'},
      {cue:'"cap downstream concurrency / protect other functions"',pick:'Reserved concurrency',why:'Capacity isolation and cap; not prewarming.'},
      {cue:'"strict cold-start latency target"',pick:'Compare provisioned concurrency / supported SnapStart',why:'Published version/alias, compatibility, spillover and paid resources matter.'},
      {cue:'"SQS batch has only some failed records"',pick:'ReportBatchItemFailures plus correct failed IDs',why:'Source visibility/redrive differ from async function destinations.'},
      {cue:'"capture exhausted async events"',pick:'Reviewed async OnFailure destination or DLQ',why:'Role permissions and event-age/retry semantics must match the invocation path.'},
      {cue:'"VPC function needs public internet"',pick:'Correct egress route/NAT or supported IPv6 design',why:'Public subnet alone does not give the function a public IP; AWS endpoints solve selected service access.'},
      {cue:'"usage plans/API keys"',pick:'API Gateway REST API feature decision',why:'API key is not authentication; use suitable IAM/authorizer/authentication.'},
      {cue:'"duplicate S3 events / overwritten source key"',pick:'Stable identity, exact VersionId and idempotent output',why:'Do not rely on delivery exactly once or an HTTP success status.'},
    ],
    stages:[
      {type:'dryrun',title:'🔬 Photo event — init, timeout, retry aur duplicate',goal:'Har step par invocation owner aur output evidence identify karo; three inline decisions answer karo.',
        nodes:[N('s3#source',150,100,{label:'Input version'}),N('lambda',490,100,{label:'Worker'}),N('s3#output',820,100,{label:'Derivatives'}),N('sqs#retry',490,300,{label:'Lambda queue',icon:'⏳'}),N('sqs#failure',820,440,{label:'Failure record'}),N('cloudwatch',150,440,{label:'Logs / metrics'})],
        edges:[{from:'s3#source',to:'lambda'},{from:'lambda',to:'s3#output'},{from:'lambda',to:'sqs#retry'},{from:'sqs#retry',to:'lambda'},{from:'sqs#retry',to:'sqs#failure'},{from:'lambda',to:'cloudwatch'}],
        panels:[{id:'attempt',title:'Execution / delivery'},{id:'data',title:'Source / output'}],
        steps:[
          {clock:'upload',say:'Versioned photo arrives. S3 pushes an async event with a URL-encoded key and VersionId. Accepted event does not yet mean derivatives exist.',flows:[{from:'s3#source',to:'lambda',tone:'busy',label:'async event'}],panels:{attempt:['Cold environment may need INIT','Standard worker initially 128 MB / timeout 3 s'],data:['Input:uploads/kurta.svg / v-photo','Output bucket separate from input']}},
          {clock:'INIT',say:'Fixture needs initialization plus CPU/IO work. At low memory, modeled execution exceeds timeout. No fixed idle-duration contract or universal VPC penalty is assumed.',nodes:{lambda:{tone:'slow',badge:'deadline risk'}},ask:{q:'First useful performance evidence?',choices:['Inspect timeout, init/handler duration and workload profile before tuning memory or capacity','Assume every VPC adds a fixed delay, then remove private database access without checking requirements','Set reserved concurrency and assume the reservation initializes warm environments for every request'],answer:0,explain:'Measure the failure stage and resource settings. VPC penalty and reserved-prewarming claims are false.'}},
          {clock:'timeout',say:'Function error reaches async retry handling. Default function-error policy permits two additional attempts. Throttle/system errors use different backoff/age handling; original source version remains stable.',flows:[{from:'lambda',to:'sqs#retry',tone:'bad',label:'function error'}],panels:{attempt:['Attempt1 fails','Function-error retries:up to 2 additional by default','Duplicates remain possible'],data:['Partial writes may exist','Use stable source version/output keys']}},
          {clock:'retry',say:'A duplicate event arrives after some derivatives were already created. Conditional create plus byte verification preserves correct outputs and fills missing derivatives.',ask:{q:'How avoid incorrect duplicate work?',choices:['Read the latest key and reuse old event identity because source overwrites need no separate handling','Use source version identity, conditionally create outputs and verify existing derivative bytes','Delete source versions after processing so duplicate deliveries cannot refer to original input data'],answer:1,explain:'Stable identity and exact-version read protect delayed events. Latest-key substitution can process a newer upload; deletion loses source evidence.'},flows:[{from:'sqs#retry',to:'lambda',tone:'busy',label:'replay safely'}]},
          {clock:'exhaustion',say:'If event errors exhaust configured retries or event age expires, the reviewed OnFailure destination captures an invocation record. SQS poll-based ingestion has a different visibility/redrive path.',flows:[{from:'sqs#retry',to:'sqs#failure',tone:'bad',label:'capture failure'}],panels:{attempt:['Async retry/age/destination explicitly configured','SQS mapping partial response is a separate contract'],data:['Failure record needs permission and an owner','Replay after diagnosing original error']}},
          {clock:'repair',say:'Right-sized worker and correct concurrency pass a direct payload test; source version and three derivative bodies agree. Output remains outside the input trigger path.',nodes:{lambda:{tone:'ok',badge:'output verified'},'s3#output':{tone:'ok',badge:'3 sizes'}},flows:[{from:'lambda',to:'s3#output',tone:'ok',label:'preserve original'}],ask:{q:'If outputs trigger the same input prefix, what matters?',choices:['Use recursive detection as complete coverage and assume unsupported trigger paths cannot create billed loops','Increase reserved concurrency to drain the loop while leaving the same output-trigger configuration active','Separate output/filter paths and monitor backlog; selected recursive detection has limited coverage'],answer:2,explain:'Avoiding the loop is primary. Selected loop detection does not guarantee every path or remove costs; more concurrency can amplify a loop.'}},
        ],lesson:'Async acceptance, handler execution and correct derivative bytes are separate milestones. Retry owner and event identity must match the path.'},
      {type:'flowlab',title:'🎛️ Memory, p99 aur paid prepared capacity',goal:'Keep at least 5 million monthly calls, workload base ≥700 ms at 1 GB and observed cold share ≥1%. Modeled p99 ≤2 s, gross monthly budget ≤₹7,000. Shrinking workload/calls or declaring zero cold events cannot win.',
        scenario:'Separate national-scale planning exercise, not the 200-photo/day current bill. CPU/IO teaching model, not an AWS benchmark: floor 100 ms, CPU part scales with memory^0.8, INIT 300 ms at 1 GB and sqrt memory effect. 10 RPS peak, 30-day month; PC 2/10 slots allocated all month, approximate peak-demand coverage. x86/arm use equal modeled speed, different current US East rates. Small payload one billed request; no free tier/credits/discounts. PC recycle INIT, API Gateway/S3/logs/network/extra storage/tax excluded. Price table in lesson; ₹88/$1.',
        knobs:[{id:'memory',label:'Function memory',min:0,max:5,step:1,value:0,labels:{0:'128 MB',1:'256 MB',2:'512 MB',3:'1,024 MB',4:'2,048 MB',5:'3,072 MB'}},{id:'base',label:'Workload duration at 1 GB',min:100,max:900,step:200,value:900,unit:' ms'},{id:'calls',label:'Monthly invocations',min:0,max:3,step:1,value:2,labels:{0:'200,000',1:'1 million',2:'5 million',3:'10 million'}},{id:'arch',label:'Architecture',min:0,max:1,step:1,value:0,labels:{0:'x86_64',1:'arm64'}},{id:'pc',label:'Prepared slots (all month)',min:0,max:2,step:1,value:0,labels:{0:'0 / on-demand',1:'2 / provisioned',2:'10 / provisioned'}},{id:'cold',label:'On-demand cold share',min:0,max:3,step:1,value:2,labels:{0:'0%',1:'1%',2:'5%',3:'10%'}}],
        model:k=>{const b=budget(k);return {readouts:[{label:'Modeled warm / INIT',value:b.m.warmMs+' / '+b.m.initMs+' ms',tone:'info'},{label:'Modeled p99',value:b.p99+' ms',tone:b.p99<=2000?'ok':'bad'},{label:'Peak concurrent environments',value:b.needed+' at 10 RPS',tone:'info'},{label:'Approx execution + requests',value:'$'+b.compute.toFixed(2)+' + $'+b.requests.toFixed(2)+'/month',tone:'info'},{label:'Approx PC allocation',value:'$'+b.allocation.toFixed(2)+'/month',tone:b.allocation?'slow':'info'},{label:'Approx total / month',value:'$'+b.total.toFixed(2)+' / ₹'+Math.round(b.total*88).toLocaleString('en-IN'),tone:b.total*88<=7000?'ok':'bad'}],verdict:{ok:b.ok,text:b.ok?'Workload, modeled latency and gross budget pass. Measure real distributions/throughput before buying prepared capacity.':'Try memory 1,024 MB, base 900 ms, 5 million calls, x86, PC 0, cold 5%. More memory can reduce modeled duration; extra PC has allocation and execution cost.'}};},check:k=>budget(k).ok,
        lesson:'Optimization preserves required work. Memory changes CPU entitlement; PC cost depends on allocation, qualified execution and spillover. Architecture speed and p99 need measurement, not memorized ratios.'},
      {type:'bins',title:'🗂️ Invocation path aur retry owner',instructions:'Source ka invocation contract classify karo; services ka naam alone enough nahi, stated integration path read karo.',bins:[{id:'sync',label:'Sync caller waits'},{id:'async',label:'Async push queue'},{id:'poll',label:'Event source mapping'}],items:[
        {text:'API Gateway proxy invokes standard function for HTTP response',bin:'sync',explain:'Caller-facing sync integration; HTTP timeout and caller retry matter.'},{text:'S3 sends object-created notification directly to Lambda',bin:'async',explain:'S3 async push; duplicate-safe processing and failure capture.'},{text:'Lambda polls Standard SQS queue in batches',bin:'poll',explain:'ESM plus visibility/redrive and partial response contract.'},{text:'Direct Invoke RequestResponse for a handler result',bin:'sync',explain:'Inspect FunctionError and response body, not just status.'},{text:'SNS delivers a topic notification directly to Lambda',bin:'async',explain:'Async function queue handling; source service delivery behavior also matters.'},{text:'Lambda polls DynamoDB Streams for changes',bin:'poll',explain:'Stream-specific mapping behavior; do not copy SQS retry rules blindly.'},{text:'EventBridge rule targets a standard Lambda function',bin:'async',explain:'Async invocation with source delivery and Lambda processing failure boundaries.'},{text:'Function URL client waits for HTTPS response',bin:'sync',explain:'Direct HTTP contract with configured auth/resource permissions.'}]},
      {type:'match',title:'🔗 Control ka actual purpose',instructions:'Each control ko matching purpose se pair karo.',pairs:[
        {left:'Reserved concurrency',right:'Exclusive capacity and maximum cap; does not prewarm',explain:'Protect capacity/downstream; reserved 0 throttles.'},{left:'Provisioned concurrency',right:'Prepared qualified environments with paid allocation',explain:'Published version/alias; spillover and runtime behavior still matter.'},{left:'ReportBatchItemFailures',right:'ESM option plus handler failed-ID response',explain:'Flag alone does not implement correct batch handling.'},{left:'Async OnFailure destination',right:'Invocation record after retry/age exhaustion',explain:'Requires permission and operational replay ownership.'},{left:'Source VersionId',right:'Exact original object for delayed event processing',explain:'Latest key can be newer than the event source.'},{left:'API key',right:'Usage-plan identifier, not caller authentication',explain:'Use suitable IAM/JWT/authorizer/authentication separately.'}]},
      {type:'triage',title:'🩺 Missing thumbnails: timeout aur throttle alag failures',symptom:'Course fixture has historical timeout logs and active load. Execution role already permits exact source/output access. Worker memory 128 MB,timeout 3 s,reserve 2. Diagnose configuration before blaming S3.',commands:[
        {cmd:'aws logs tail /aws/lambda/photo-resize',out:'fixture-request-old Task timed out after 3.00 seconds\nTooManyRequestsException: ReservedFunctionConcurrentInvocationLimitExceeded',clue:true,note:'Execution deadline failure and admission throttling are distinct.'},{cmd:'aws lambda get-function-configuration --function-name photo-resize',out:'{"MemorySize":128,"Timeout":3,"State":"Active","LastUpdateStatus":"Successful"}',clue:true,note:'Low-memory benchmark and short deadline need review.'},{cmd:'aws lambda get-function-concurrency --function-name photo-resize',out:'{"ReservedConcurrentExecutions":2}',clue:true,note:'Only two concurrent executions allowed; does not prewarm.'},{cmd:'aws iam list-roles',out:'{"Roles":[{"RoleName":"shop-lambda","Arn":"arn:aws:iam::123456789012:role/shop-lambda"}]}',clue:false,note:'Role presence alone proves no policy, but this fixture supplies a reviewed source/output policy.'}],questions:[
        Q('What do both observed error paths imply?','Review execution deadline/resource profile and reserved admission capacity separately',['Raise timeout alone because throttled invocations are already running inside the handler','Change only the S3 key because admission throttles always mean source object is absent','Buy provisioned slots on $LATEST because reserved capacity automatically prewarms them'],0,'Timeout occurs during execution; throttle is admission/capacity. Timeout alone cannot fix cap; missing key is not throttle; PC needs qualified versions and reserve is not prewarming.'),
        Q('Which repair also requires output proof?','Tune from benchmark, wait update, set reviewed cap and verify body plus exact derivatives',['Raise memory to maximum and declare success from update configuration status alone','Delete the function and source versions so old timeout evidence no longer appears','Disable async retries and assume duplicate messages cannot reach the handler again'],1,'Tune capacity/latency, then verify data. Max memory/status alone do not prove cost or output; deletion loses evidence; disabling retries does not ensure single delivery.')
      ]},
      {type:'terminal',title:'🖥️ Mission — repair worker and verify source-version outputs',instructions:'Inspect ls/cat, function config/concurrency and logs first. Seven intended steps; wait for update and mapping readiness. Invoke response is in-memory, not a host file.',
        goal:'<ol><li>Right-size original <code>photo-resize</code>: memory 512..2048 MB, timeout 15..30 s, modeled p99 ≤2 s.</li><li>Set reserved cap 10..20 and meet the fixture 10 RPS capacity.</li><li>Configure async retries 2, maximum event age 3600 s, and OnFailure queue <code>photo-failures</code>.</li><li>Keep one Enabled <code>photo-jobs</code> mapping, batch 10 and <code>ReportBatchItemFailures</code>.</li><li>Invoke <code>event.json</code> into <code>invoke.json</code>; verify successful current-$LATEST body and three exact v-photo derivatives.</li></ol><p>Preserve source version, private buckets, role, queues and courier function. Wait/list advances documented fixture readiness; no real runtime, elapsed time or trigger delivery claim.</p>',
        account:seed(),files:{'event.json':file(EVENT()),'destination.json':file(DEST()),'role-policy.json':file({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:GetObject','s3:GetObjectVersion'],Resource:'arn:aws:s3:::shop-uploads/uploads/*'},{Effect:'Allow',Action:['s3:PutObject','s3:GetObject'],Resource:'arn:aws:s3:::shop-thumbs/thumbs/*'},{Effect:'Allow',Action:['sqs:ReceiveMessage','sqs:DeleteMessage','sqs:GetQueueAttributes'],Resource:JOBS},{Effect:'Allow',Action:'sqs:SendMessage',Resource:FAILURES}]})},tasks:TASKS,success:AG.allOf(TASKS),solution:SOLUTION,
        hints:SOLUTION.map((c,i)=>c+[' — request benchmark-based memory/deadline change',' — wait for configuration; old settings remain before fixture completion',' — reserve capacity/cap, not prewarming',' — inspect destination.json; function async settings differ from SQS retry',' — configure jobs mapping plus handler partial-response contract',' — observe mapping Enabled in documented fixture',' — final payload/body/source-version check; status200 alone not success'][i]),
        successText:'Original source version and three derivative bodies agree. Current function timing/capacity, async failure config and mapping readiness pass. This is a bounded interpreter fixture; local lab separately executes real SVG handler and verifies Moto S3 bytes.'},
      {type:'docker',title:'🧪 Lab14 — actual host handler plus Moto metadata',project:'14-lambda-handler-config',goal:'Run real trusted-SVG handler checks, then actual Lambda config CLI requests. Docker invocation remains unverified; inspect captured FunctionError instead of claiming runtime success.',why:'Direct code execution, deployment metadata and trigger/runtime delivery provide different evidence.',steps:[
        {text:'Use existing Moto and lab venv. See README; no automatic install or shared reset.',cmd:'cd docker-labs && source env.sh && cd 14-lambda-handler-config',expect:'Loopback 4566 and dummy test/test. Every metadata CLI service explicitly pins endpoint.'},
        {text:'Execute trusted SVG handler and byte/duplicate/partial-batch checks on host.',cmd:'../.venv/bin/python -I test_handler.py',expect:'19 checks; first 3 writes, repeat 0 writes/3 verified duplicates; four concurrent deliveries 3 writes/9 duplicates; failed ID bad-1 only; exact old version preserved; test buckets cleaned.'},
        {text:'Read controller then create isolated metadata resources and exercise actual CLI.',cmd:'../.venv/bin/python -I lab.py setup && ../.venv/bin/python -I lab.py exercises',expect:'Memory 1024, Timeout 15, Update Successful; reserved 10, async config and Enabled partial mapping. Invoke 200 includes FunctionError Handled with Docker socket error; PC API 404.'},
        {text:'Clean only saved metadata resources.',cmd:'../.venv/bin/python -I lab.py cleanup',expect:'Function and owned bucket lookups return two empty arrays; no shared reset.'}
      ],observe:Q('What did the two local lab parts establish?','Host handler wrote verified SVG bytes; Moto metadata does not prove Docker invocation',['HTTP200 proved the deployed Lambda ran successfully even though FunctionError was present','Provisioned API404 proved initialized execution environments were ready in the background','An Enabled mapping readback alone established that queue messages were consumed and outputs delivered'],2,'Host bytes/tests are actual execution evidence. Invoke had function error and Docker missing; PC404 is unsupported; empty queues/buckets cannot prove delivery.')},
      {type:'quiz',title:'🎓 Lambda + API choices',questions:[
        Q('S3 retries the same event after the source key has changed. Safe input strategy?','Read the event exact VersionId and use stable idempotent derivative keys',['Read whichever object version is latest and assume old events cannot arrive after overwrite','Delete old versions before processing so duplicate deliveries have no source left to read','Treat S3 notifications as exactly once and skip all conditional output checks'],3,'Exact version preserves event meaning. Latest can be newer; deletion loses evidence; notifications can duplicate so stable conditional operations matter.'),
        Q('Reserved concurrency10 mainly provides what?','Exclusive capacity and cap for the function, without pre-initializing environments',['Ten always-warm execution environments with guaranteed latency for every incoming request','Ten requests per second regardless of function duration and account-level throttling','A paid cache that automatically removes repeated S3 event deliveries before execution'],0,'Reserved concurrency isolates/caps in-flight capacity. It does not prewarm, equal fixed RPS or deduplicate events.'),
        Q('A direct synchronous invoke returns200 plus FunctionError. Best interpretation?','Invocation transport succeeded; inspect function error body and actual output before declaring success',['The function completed every business side effect because HTTP200 implies exactly-once completion','Lambda automatically retries every synchronous request twice before returning the same response','Increasing only the function timeout will repair any missing object or invalid handler configuration'],1,'Status covers invocation transport; FunctionError/body/data decide execution outcome. Sync retry belongs to caller; timeout is not a universal repair.'),
        Q('SQS batch has one bad record and several good records. Correct partial failure contract?','Enable ReportBatchItemFailures and return only failed message IDs; retain idempotency',['Enable function async retry 2 and remove source queue visibility/redrive settings completely','Return a generic error string while assuming the mapping identifies every good record automatically','Acknowledge the entire batch because the function HTTP status is200 even with invalid records'],2,'Mapping option and handler failed-ID response both required. SQS retry differs from function async settings; generic errors can replay full batch and blanket acknowledgement loses bad records.'),
        Q('Latency-sensitive function wants provisioned concurrency. Which setup is valid?','Use a published version/alias and budget prepared allocation, execution and spillover',['Configure $LATEST directly and assume every request becomes free after first initialization','Set reserved concurrency only because reserved capacity is the same warm-runtime service','Enable SnapStart and provisioned concurrency together without reviewing documented compatibility'],3,'PC is qualified and billed; spillover remains. $LATEST unsupported, reserve not prewarming, current SnapStart/PC incompatible.'),
        Q('Private-resource Lambda needs outbound public API access. Accurate guidance?','Review VPC egress routing/NAT or supported IPv6 design; subnet label alone is insufficient',['Move the function into a public subnet and assume Lambda receives a public instance IP automatically','Remove every VPC attachment because a fixed100ms delay applies to all private database invocations','Create an S3 gateway endpoint and assume every unrelated public internet API becomes reachable'],0,'Network path matters. Public subnet does not assign Lambda a public IP; no universal VPC delay; service endpoint covers selected services, not all internet targets.'),
        Q('API requires usage plans/API keys. Which statement keeps auth and features clear?','REST API is a candidate; API keys identify usage and do not replace caller authentication',['HTTP API keys authenticate every caller and always provide all REST API usage-plan controls','Function URL NONE automatically adds JWT identity verification for every public request','Throttling quota guarantees every denial-of-service request is blocked without other controls'],1,'Choose REST feature need and separate auth. HTTP features differ, NONE does not add JWT, quota throttling is not blanket DDoS protection.'),
        Q('Current standard on-demand Event Function payload/deadline statement?', 'Standard timeout 900 s; buffered sync 6 MB each, async 1 MB; other Lambda models have separate scope',['Buffered synchronous input supports 200 MB because streamed-response quota also applies to requests','Async payload remains 256 KB and every Lambda model shares the same 900-second invocation ceiling','Increasing API Gateway timeout automatically increases standard Lambda maximum execution duration'],2,'Current standard limits and scope matter. Scaling is bounded; async increased to1MB and newer models differ; gateway timeout does not change function ceiling.')
      ]}
    ],
    interview:{title:'Interview — ownership, latency aur replay evidence',instructions:'Choose the contract; then repair partial-batch configuration and verify duplicate-safe response.',questions:[
      Q('Interviewer: “More memory always wastes money or always speeds up fourfold?”','Neither rule holds; benchmark CPU/IO, latency and GB-seconds for the actual workload',['More memory always increases cost because billed duration is independent of CPU and workload','Every memory doubling guarantees twice the speed and exact same total monthly invoice','Memory never affects initialization or execution because all Lambda functions receive identical CPU'],3,'CPU entitlement changes; actual workload duration and billed GB-seconds decide. Fixed speed/cost claims ignore IO, init and dependencies.'),
      Q('Courier webhook may retry after response loss. Core correctness requirement?', 'Verify request authenticity and make the business update idempotent using stable identity',['Trust API key alone as authentication and perform the business update for every duplicate delivery','Keep the only processed-event registry in process memory so every execution environment shares it','Return success before durably accepting work and assume the caller never retries after a lost response'],0,'Authenticity and idempotency matter. API keys are not authentication; process memory not shared/durable; premature acknowledgement can lose work.'),
      Q('An architecture has heavy Java/Python/.NET initialization. SnapStart discussion?', 'Review current runtime/Region support, snapshot-safe uniqueness and compatibility/cost',['Assume SnapStart is Java-only forever, cannot support images and is free for every runtime','Combine SnapStart with PC and EFS without reviewing any current support restrictions','Use a snapshot of every random identifier and open connection without any restore-time checks'],1,'Current support expanded; uniqueness/connections and limits still matter. Old Java/ZIP-only/free blanket claims are stale; PC/EFS combinations and snapshot state require review.'),
      Q('One function receives S3 async events and a Standard SQS mapping. Retry configuration?', 'Treat Lambda async settings and SQS visibility/redrive/partial responses as separate contracts',['Apply function async retry 2 and assume every SQS message is deleted after exactly two receives','Use queue visibility alone and remove idempotency because Standard SQS guarantees no duplicates','Use OnFailure destination as a universal substitute for source queue DLQ/redrive permissions'],2,'Retry owner differs. Function async settings do not establish SQS receives/deletion; Standard can duplicate; destinations do not replace source queue redrive.'),
      {terminal:(()=>{const a=seed(),f=a.lambdas[0];f.memory=1024;f.timeout=15;f.reservedConcurrency=10;f.asyncConfigs={$LATEST:{MaximumRetryAttempts:2,MaximumEventAgeInSeconds:3600,DestinationConfig:DEST()}};
        a.eventSourceMappings=[{uuid:'11111111-1111-4111-8111-111111111111',functionName:'photo-resize',eventSourceArn:JOBS,batchSize:10,responseTypes:[],state:'Enabled'}];
        a.buckets[1].objects=[64,128,256].map(size=>({key:'thumbs/'+encodeURIComponent('shop-uploads/uploads/kurta.svg/v-photo')+'/'+size+'.svg',size:SVG.length,sourceVersion:'v-photo',width:size,height:size,body:SVG.replace('width="320"','width="'+size+'"').replace('height="240"','height="'+size+'"')}));
        const batch={Records:[{eventSource:'aws:sqs',messageId:'good-1',body:JSON.stringify(EVENT())},{eventSource:'aws:sqs',messageId:'bad-1',body:'invalid-json'}]},solution=['aws lambda update-event-source-mapping --uuid 11111111-1111-4111-8111-111111111111 --function-response-types ReportBatchItemFailures','aws lambda get-event-source-mapping --uuid 11111111-1111-4111-8111-111111111111','aws lambda invoke --function-name photo-resize --cli-binary-format raw-in-base64-out --payload file://batch.json batch-result.json'];
        const tasks=[...TASKS.filter((_,i)=>i!==4),{text:'Successful current batch result reports only bad-1; good derivative set unchanged',check:s=>{const r=s.downloads&&s.downloads['batch-result.json'];return invokeProof(s,'batch-result.json')&&r.body&&JSON.stringify(r.body.batchItemFailures)===JSON.stringify([{itemIdentifier:'bad-1'}]);}}];
        return {title:'🖥️ Partial batch plus duplicate-safe output',goal:'Config/timing and correct derivatives already exist. Mapping has no partial-response option. Update original mapping, observe Enabled, invoke batch.json into batch-result.json. Only bad-1 should fail; original three derivatives must remain exact. Direct payload test proves handler response contract, not actual queue deletion or automatic delivery.',account:a,files:{'batch.json':file(batch)},tasks,success:AG.allOf(tasks),solution,hints:solution.map((c,i)=>c+[' — configure existing mapping instead of duplicate creation',' — observe mapping readiness in fixture',' — final partial-result and unchanged-byte checks'][i]),successText:'Only bad-1 appears in partial response. Correct derivative bodies remain unchanged; source versions/role/queues preserved. Source poller acknowledgement and real deployed delivery still need independent runtime evidence.'};})()}
    ]},
    success:['Invocation path aur retry owner identify kar sakta hoon','Memory/timeout, reserved vs provisioned capacity aur cold-init cost compare kar sakta hoon','HTTP endpoint/auth/timeout ka requirement-based choice justify kar sakta hoon','Exact-version/idempotent output and partial-batch correctness evidence verify kar sakta hoon'],
    homework:'<p><b>Optional approved AWS sandbox only; billable:</b> confirm current function model/Region quotas, budget for execution/INIT, API, logs, storage and network. Deploy reviewed runtime/role and versioned source, separate output trigger path, stable event identity and conditional writes. Configure actual source permission/filter and async failure capture or SQS visibility/redrive/partial-response contract. Upload a small approved fixture; inspect real invocation logs, source version and three output bytes. Replay the event and simulate one failure; verify no corrupt duplicate outputs and a useful failure record. For courier endpoint, validate authenticity, idempotency and supported auth/timeouts. Benchmark cold/warm distribution at required arrival rate before PC/SnapStart; use qualified version/alias and current compatibility rules. Docker runtime sections remain unverified until installed/network reviewed. Cleanup source notifications/mappings, test PC, endpoints/API stages/log groups, exact disposable object versions, queues, function versions/aliases/role/policies; preserve production/shared data and retained audit evidence.</p>',
    cards:[{front:'Three invocation paths?',back:'Sync caller waits/retries; async push uses function queue/retry/age; poll mapping uses source-specific batch/retry semantics. No universal two-retry rule.'},{front:'Reserved vs provisioned?',back:'Reserved isolates/caps concurrency without prewarming. Provisioned prepares published-version/alias environments with extra allocation/execution charges; spillover can be cold.'},{front:'Current standard limits?',back:'Timeout900s, memory 128..10,240 MB, /tmp 512..10,240 MB. Buffered sync 6 MB each, async 1 MB; streamed response 200 MB separate. Other Lambda models have different scope.'},{front:'Cold start fixed idle timer?',back:'No. Measure init/handler distribution; benchmark package/memory/architecture and supported SnapStart/PC. VPC has no universal fixed penalty.'},{front:'SQS partial batch?',back:'Enable ReportBatchItemFailures and return exact failed message IDs. Keep idempotency, visibility/redrive and FIFO ordering requirements distinct.'},{front:'Status200 proves success?',back:'No. Inspect FunctionError, payload and actual correct data/version. Async202 accepts an event; DryRun204 does not execute the handler.'},{front:'Avoid recursive/duplicate work?',back:'Separate output/filter, exact source version, stable IDs and conditional writes with byte verification. Selected recursive detection is not a universal safety or cost guarantee.'},{front:'API key / function URL?',back:'API key usage identifier is not authentication. REST/HTTP/WebSocket/URL feature sets differ. New function URLs require InvokeFunctionUrl plus InvokeFunction permissions under current policy rules.'}]
  }]);
})();
